-- The passage's ṣarf (step 3, after Words): for each focus word, its الصرف الصغير in the
-- textbook's order, every مصدر, its other صيغ, واحد/جمع with the Qurʾān's plurals, the prepositions
-- its verb takes in the Qurʾān and what each one does, the root's other Qurʾānic verbs as family
-- lines, the word's meaning range across the Qurʾān, its near-synonyms, and a plain root picture.
-- Every label is a GT term. Every Qurʾān citation is (surah, ayah, needle): the needle is the
-- bare text, matched in qr_ayah.text_bare and cut from the muṣḥaf text when a drill is dealt.
-- First filled for Ghāfir 40:1–3; reviewed by the owner before it was dealt.

CREATE TABLE IF NOT EXISTS qr_sarf_verb (
  id            TEXT PRIMARY KEY,               -- SV:<root>:<form>[:<bāb>]
  root          TEXT NOT NULL,
  form_gt       TEXT NOT NULL,                  -- GT:form_family:form_*
  bab_gt        TEXT,                           -- GT:form_family:bab_* (form I)
  root_type_gt  TEXT,
  route_gt      TEXT,                           -- GT:taddiya_route:*
  maani_gt      TEXT,                           -- GT:sigha_maani:* (what the form adds)
  meaning_en    TEXT NOT NULL,
  madi TEXT NOT NULL, mudari TEXT NOT NULL,
  masadir_json  TEXT NOT NULL,                  -- every maṣdar, first the usual
  fail TEXT, fail_gt TEXT,                      -- فهو …: اسم الفاعل or the صفة مشبهة
  madi_majhul TEXT, mudari_majhul TEXT, maful TEXT,   -- NULL: no مجهول (لازم)
  amr TEXT, nahy TEXT,
  zarf_json TEXT, ala_json TEXT,
  others_json   TEXT,                           -- [[form, GT, pattern, meaning]] — مبالغة، تفضيل …
  quran_n       INTEGER NOT NULL DEFAULT 0,     -- how often the verb is used in the Qurʾān
  cite_json     TEXT,                           -- {surah, ayah, needle}
  full          INTEGER NOT NULL DEFAULT 0,     -- 1: the whole table; 0: a family line
  note_en       TEXT,
  sort          INTEGER NOT NULL DEFAULT 0,
  status        TEXT NOT NULL DEFAULT 'live'
);
CREATE INDEX IF NOT EXISTS idx_qr_sarf_verb_root ON qr_sarf_verb(root, sort);

CREATE TABLE IF NOT EXISTS qr_sarf_prep (
  id          TEXT PRIMARY KEY,
  verb_id     TEXT NOT NULL,
  prep_ar     TEXT NOT NULL,
  prep_gt     TEXT,                             -- GT:harf_maani:*
  usage_ar    TEXT NOT NULL,
  meaning_en  TEXT NOT NULL,
  cite_json   TEXT NOT NULL,
  sort        INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_qr_sarf_prep_verb ON qr_sarf_prep(verb_id);

CREATE TABLE IF NOT EXISTS qr_sarf_word (
  surah INTEGER NOT NULL, ayah INTEGER NOT NULL, word_index INTEGER NOT NULL,
  word_ar      TEXT NOT NULL,
  root         TEXT NOT NULL,
  verb_id      TEXT,                            -- NULL: a noun with no Qurʾānic verb (ذَنْب)
  sigha_gt     TEXT,
  pattern_ar   TEXT,
  here_en      TEXT NOT NULL,                   -- what it means in this āyah
  plurals_json TEXT,                            -- [{ar, cite}]
  prep_json    TEXT,                            -- {ar, gt, how}: the preposition with it here
  PRIMARY KEY (surah, ayah, word_index)
);
CREATE INDEX IF NOT EXISTS idx_qr_sarf_word_root ON qr_sarf_word(root);

CREATE TABLE IF NOT EXISTS qr_sarf_sense (
  id        TEXT PRIMARY KEY,                   -- SS:<root>:<n>
  root      TEXT NOT NULL,
  lemma_ar  TEXT NOT NULL,
  sense_en  TEXT NOT NULL,
  sense_ar  TEXT,
  cites_json TEXT NOT NULL,                     -- [{surah, ayah, needle}]
  here      INTEGER NOT NULL DEFAULT 0,         -- the sense in the passage
  sort      INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_qr_sarf_sense_root ON qr_sarf_sense(root, sort);

CREATE TABLE IF NOT EXISTS qr_sarf_near (
  id        TEXT PRIMARY KEY,                   -- NS40:…
  root      TEXT NOT NULL,                      -- the focus word's root
  focus_ar  TEXT NOT NULL,
  title_en  TEXT NOT NULL,
  title_ar  TEXT NOT NULL,
  members_json TEXT NOT NULL,                   -- [{ar, en, cite}]
  status    TEXT NOT NULL DEFAULT 'live'
);

