INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:غفر:I', 'غفر', 'GT:form_family:form_i', 'GT:form_family:bab_daraba', 'GT:root_type:sound', 'GT:taddiya_route:binafsihi', NULL, 'to forgive (to cover over a sin)', 'غَفَرَ', 'يَغْفِرُ', '["غَفْرًا", "غُفْرَانًا", "مَغْفِرَةً"]', 'غَافِرٌ', 'GT:derivation_type:active_participle', 'غُفِرَ', 'يُغْفَرُ', 'مَغْفُورٌ لَهُ', 'اِغْفِرْ', 'لَا تَغْفِرْ', '["مَغْفِرٌ"]', '["مِغْفَرٌ"]', '[["غَفُورٌ", "GT:derivation_type:mubalagha", "فَعُول", "forgiving much"], ["غَفَّارٌ", "GT:derivation_type:mubalagha", "فَعَّال", "forgiving again and again"]]', 65, '{"surah": 39, "ayah": 53, "needle": "يغفر الذنوب جميعا"}', 1, 'The tool-noun مِغْفَر is the helmet that covers the head — the root picture. مَغْفِرَة is a مصدر ميمي.', 14);
