INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:توب:I', 'توب', 'GT:form_family:form_i', 'GT:form_family:bab_nasara', 'GT:root_type:hollow_w', 'GT:taddiya_route:biharf', NULL, 'to turn back (in repentance); of God: to turn to someone in mercy', 'تَابَ', 'يَتُوبُ', '["تَوْبًا", "تَوْبَةً", "مَتَابًا"]', 'تَائِبٌ', 'GT:derivation_type:active_participle', 'تِيبَ عَلَيْهِ', 'يُتَابُ عَلَيْهِ', 'مَتُوبٌ عَلَيْهِ', 'تُبْ', 'لَا تَتُبْ', '["مَتَابٌ"]', NULL, '[["تَوَّابٌ", "GT:derivation_type:mubalagha", "فَعَّال", "turning again and again"]]', 63, '{"surah": 66, "ayah": 8, "needle": "توبوا الي الله"}', 1, 'Intransitive: its مجهول is made with its preposition — تِيبَ عَلَيْهِ.', 21);
INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:شدد:I:daraba', 'شدد', 'GT:form_family:form_i', 'GT:form_family:bab_daraba', 'GT:root_type:doubled', 'GT:taddiya_route:lazim', NULL, 'to be strong, hard, severe', 'شَدَّ', 'يَشِدُّ', '["شِدَّةً"]', 'شَدِيدٌ', 'GT:derivation_type:sifa_mushabbaha', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[["أَشَدُّ", "GT:derivation_type:tafdil", "أَفْعَل", "stronger, more severe"]]', 0, NULL, 1, 'A verb of state: no مجهول; its describing word is the صفة مشبهة شَدِيد.', 22);
INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:شدد:I:nasara', 'شدد', 'GT:form_family:form_i', 'GT:form_family:bab_nasara', 'GT:root_type:doubled', 'GT:taddiya_route:binafsihi', NULL, 'to bind fast; to strengthen', 'شَدَّ', 'يَشُدُّ', '["شَدًّا"]', 'شَادٌّ', 'GT:derivation_type:active_participle', 'شُدَّ', 'يُشَدُّ', 'مَشْدُودٌ', 'اُشْدُدْ', 'لَا تَشُدَّ', '["مَشَدٌّ"]', NULL, NULL, 6, '{"surah": 47, "ayah": 4, "needle": "فشدوا الوثاق"}', 1, 'Same letters, another باب: شَدَّ يَشِدُّ (be strong) and شَدَّهُ يَشُدُّهُ (bind it fast).', 23);
