INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:عقب:III', 'عقب', 'GT:form_family:form_iii', NULL, 'GT:root_type:sound', 'GT:taddiya_route:binafsihi', NULL, 'to punish (in return for a deed)', 'عَاقَبَ', 'يُعَاقِبُ', '["عِقَابًا", "مُعَاقَبَةً"]', 'مُعَاقِبٌ', 'GT:derivation_type:active_participle', 'عُوقِبَ', 'يُعَاقَبُ', 'مُعَاقَبٌ', 'عَاقِبْ', 'لَا تُعَاقِبْ', '["مُعَاقَبٌ"]', NULL, NULL, 6, '{"surah": 16, "ayah": 126, "needle": "فعاقبوا بمثل ما عوقبتم به"}', 1, NULL, 25);
INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:عقب:II', 'عقب', 'GT:form_family:form_ii', NULL, 'GT:root_type:sound', 'GT:taddiya_route:binafsihi', NULL, 'to turn back; to overturn (a ruling)', 'عَقَّبَ', 'يُعَقِّبُ', '["تَعْقِيبًا"]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, '{"surah": 13, "ayah": 41, "needle": "لا معقب لحكمه"}', 0, NULL, 26);
