INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:طول:I', 'طول', 'GT:form_family:form_i', 'GT:form_family:bab_nasara', 'GT:root_type:hollow_w', 'GT:taddiya_route:lazim', NULL, 'to be long, to last long', 'طَالَ', 'يَطُولُ', '["طُولًا", "طَوْلًا"]', 'طَوِيلٌ', 'GT:derivation_type:sifa_mushabbaha', NULL, NULL, NULL, 'طُلْ', 'لَا تَطُلْ', '["مَطَالٌ"]', NULL, NULL, 3, '{"surah": 57, "ayah": 16, "needle": "فطال عليهم الامد"}', 1, 'Two مصادر, two meanings: طُول is length; طَوْل is a bounty that reaches far — the word in ذِي الطَّوْلِ.', 28);
INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:طول:VI', 'طول', 'GT:form_family:form_vi', NULL, 'GT:root_type:hollow_w', 'GT:taddiya_route:lazim', NULL, 'to grow long (of time)', 'تَطَاوَلَ', 'يَتَطَاوَلُ', '["تَطَاوُلًا"]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '{"surah": 28, "ayah": 45, "needle": "فتطاول عليهم العمر"}', 0, NULL, 29);
INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:اله:I', 'اله', 'GT:form_family:form_i', 'GT:form_family:bab_fataha', 'GT:root_type:mahmuz_fa', 'GT:taddiya_route:binafsihi', NULL, 'to worship', 'أَلَهَ', 'يَأْلَهُ', '["إِلَاهَةً", "أُلُوهَةً", "أُلُوهِيَّةً"]', 'آلِهٌ', 'GT:derivation_type:active_participle', 'أُلِهَ', 'يُؤْلَهُ', 'مَأْلُوهٌ', 'اِيلَهْ', 'لَا تَأْلَهْ', '["مَأْلَهٌ"]', NULL, NULL, 0, NULL, 1, 'The Qurʾān does not use the verb. إِلَٰه is on فِعَال in the sense of مَفْعُول: the one worshipped (مَأْلُوه).', 30);
INSERT OR REPLACE INTO qr_sarf_verb (id, root, form_gt, bab_gt, root_type_gt, route_gt, maani_gt, meaning_en, madi, mudari, masadir_json, fail, fail_gt, madi_majhul, mudari_majhul, maful, amr, nahy, zarf_json, ala_json, others_json, quran_n, cite_json, full, note_en, sort) VALUES ('SV:صير:I', 'صير', 'GT:form_family:form_i', 'GT:form_family:bab_daraba', 'GT:root_type:hollow_y', 'GT:taddiya_route:biharf', NULL, 'to come to (an end), to return to; to become', 'صَارَ', 'يَصِيرُ', '["صَيْرًا", "مَصِيرًا", "صَيْرُورَةً"]', 'صَائِرٌ', 'GT:derivation_type:active_participle', 'صِيرَ إِلَيْهِ', 'يُصَارُ إِلَيْهِ', 'مَصِيرٌ إِلَيْهِ', 'صِرْ', 'لَا تَصِرْ', '["مَصِيرٌ"]', NULL, NULL, 1, '{"surah": 42, "ayah": 53, "needle": "الا الي الله تصير الامور"}', 1, 'مَصِير is both its مصدر ميمي (the returning) and its ظرف (the place of return).', 31);
INSERT OR REPLACE INTO qr_sarf_prep (id, verb_id, prep_ar, prep_gt, usage_ar, meaning_en, cite_json, sort) VALUES ('SP:SV:نزل:II:0', 'SV:نزل:II', 'عَلَى', 'GT:harf_maani:ala_istila', 'نَزَّلَ عَلَى', 'to send down upon — the one who receives it', '{"surah": 3, "ayah": 3, "needle": "نزل عليك الكتاب"}', 0);
