INSERT OR REPLACE INTO qr_sarf_prep (id, verb_id, prep_ar, prep_gt, usage_ar, meaning_en, cite_json, sort) VALUES ('SP:SV:كتب:I:3', 'SV:كتب:I', 'عَلَى', 'GT:harf_maani:ala_istila', 'كَتَبَ عَلَى', 'to make binding on, to prescribe for', '{"surah": 2, "ayah": 183, "needle": "كتب عليكم الصيام"}', 3);
INSERT OR REPLACE INTO qr_sarf_prep (id, verb_id, prep_ar, prep_gt, usage_ar, meaning_en, cite_json, sort) VALUES ('SP:SV:كتب:I:4', 'SV:كتب:I', 'لِ', 'GT:harf_maani:lam_ikhtisas', 'كَتَبَ لِ', 'to decree for someone, as their share', '{"surah": 9, "ayah": 51, "needle": "ما كتب الله لنا"}', 4);
