INSERT OR REPLACE INTO qr_sarf_prep (id, verb_id, prep_ar, prep_gt, usage_ar, meaning_en, cite_json, sort) VALUES ('SP:SV:كتب:I:6', 'SV:كتب:I', 'مَعَ', 'GT:harf_maani:maa_musahaba', 'كَتَبَ مَعَ', 'to count among, to list with', '{"surah": 3, "ayah": 53, "needle": "فاكتبنا مع الشاهدين"}', 6);
INSERT OR REPLACE INTO qr_sarf_prep (id, verb_id, prep_ar, prep_gt, usage_ar, meaning_en, cite_json, sort) VALUES ('SP:SV:عزز:I:daraba:7', 'SV:عزز:I:daraba', 'عَلَى', 'GT:harf_maani:ala_istila', 'عَزِيزٌ عَلَى', 'hard on someone, painful to them', '{"surah": 9, "ayah": 128, "needle": "عزيز عليه ما عنتم"}', 7);
INSERT OR REPLACE INTO qr_sarf_prep (id, verb_id, prep_ar, prep_gt, usage_ar, meaning_en, cite_json, sort) VALUES ('SP:SV:عزز:I:daraba:8', 'SV:عزز:I:daraba', 'عَلَى', 'GT:harf_maani:ala_istila', 'وَمَا ذَلِكَ عَلَى اللَّهِ بِعَزِيزٍ', 'not hard for God at all', '{"surah": 14, "ayah": 20, "needle": "وما ذلك علي الله بعزيز"}', 8);
