INSERT OR REPLACE INTO qr_sarf_near (id, root, focus_ar, title_en, title_ar, members_json) VALUES ('NS40:dhanb', 'ذنب', 'ذَنْب', 'Words for sin', 'الذَّنْبُ وَأَخَوَاتُهُ', '[{"ar": "ذَنْب", "en": "a wrong deed whose result follows behind it, like a tail", "cite": {"surah": 40, "ayah": 3, "needle": "غافر الذنب"}}, {"ar": "إِثْم", "en": "a wrong that holds a person back from good", "cite": {"surah": 2, "ayah": 219, "needle": "قل فيهما اثم كبير"}}, {"ar": "خَطِيئَة", "en": "a wrong that misses the mark — and can surround a person", "cite": {"surah": 2, "ayah": 81, "needle": "واحاطت به خطيئته"}}, {"ar": "جُنَاح", "en": "blame — “no blame on you”", "cite": {"surah": 2, "ayah": 158, "needle": "فلا جناح عليه"}}]');
INSERT OR REPLACE INTO qr_sarf_near (id, root, focus_ar, title_en, title_ar, members_json) VALUES ('NS40:iqab', 'عقب', 'عِقَاب', 'Words for punishment', 'العِقَابُ وَأَخَوَاتُهُ', '[{"ar": "عِقَاب", "en": "punishment that comes after the deed, in return for it", "cite": {"surah": 40, "ayah": 3, "needle": "شديد العقاب"}}, {"ar": "عَذَاب", "en": "pain and torment that is felt", "cite": {"surah": 2, "ayah": 10, "needle": "ولهم عذاب اليم"}}, {"ar": "نَكَال", "en": "a punishment that warns others away", "cite": {"surah": 5, "ayah": 38, "needle": "نكالا من الله"}}, {"ar": "بَأْس", "en": "a forceful blow, sudden might", "cite": {"surah": 6, "ayah": 43, "needle": "جاءهم باسنا"}}]');
INSERT OR REPLACE INTO qr_sarf_near (id, root, focus_ar, title_en, title_ar, members_json) VALUES ('NS40:ghafr', 'غفر', 'غَفَرَ', 'Forgiving', 'الغُفْرَانُ وَالعَفْوُ وَالصَّفْحُ', '[{"ar": "غَفَرَ", "en": "to cover the sin so its harm does not reach the person", "cite": {"surah": 39, "ayah": 53, "needle": "يغفر الذنوب جميعا"}}, {"ar": "عَفَا", "en": "to wipe the wrong away, to let it go", "cite": {"surah": 2, "ayah": 109, "needle": "فاعفوا واصفحوا"}}, {"ar": "صَفَحَ", "en": "to turn the page — to move on without blame", "cite": {"surah": 24, "ayah": 22, "needle": "وليعفوا وليصفحوا"}}]');
INSERT OR REPLACE INTO qr_sarf_near (id, root, focus_ar, title_en, title_ar, members_json) VALUES ('NS40:tawb', 'توب', 'تَابَ', 'Turning back', 'التَّوْبَةُ وَالإِنَابَةُ وَالرُّجُوعُ', '[{"ar": "تَابَ", "en": "to turn back from sin to God", "cite": {"surah": 66, "ayah": 8, "needle": "توبوا الي الله"}}, {"ar": "أَنَابَ", "en": "to turn to God again and again, with the whole heart", "cite": {"surah": 30, "ayah": 31, "needle": "منيبين اليه"}}, {"ar": "رَجَعَ", "en": "to return — any return", "cite": {"surah": 2, "ayah": 156, "needle": "انا لله وانا اليه راجعون"}}, {"ar": "صَارَ", "en": "to end up at a place or state", "cite": {"surah": 42, "ayah": 53, "needle": "الا الي الله تصير الامور"}}]');
INSERT OR REPLACE INTO qr_sarf_near (id, root, focus_ar, title_en, title_ar, members_json) VALUES ('NS40:tawl', 'طول', 'طَوْل', 'Bounty and means', 'الطَّوْلُ وَالسَّعَةُ وَالفَضْلُ', '[{"ar": "طَوْل", "en": "a bounty that reaches far, beyond others", "cite": {"surah": 40, "ayah": 3, "needle": "ذي الطول"}}, {"ar": "سَعَة", "en": "wide means — having plenty", "cite": {"surah": 65, "ayah": 7, "needle": "لينفق ذو سعة من سعته"}}, {"ar": "فَضْل", "en": "more than what is owed — extra goodness", "cite": {"surah": 2, "ayah": 105, "needle": "والله ذو الفضل العظيم"}}]');
INSERT OR REPLACE INTO qr_sarf_near (id, root, focus_ar, title_en, title_ar, members_json) VALUES ('NS40:nuzul', 'نزل', 'نَزَّلَ', 'Sending down: نَزَّلَ and أَنْزَلَ', 'نَزَّلَ وَأَنْزَلَ', '[{"ar": "نَزَّلَ", "en": "sent down in parts, over time — the Qurʾān", "cite": {"surah": 3, "ayah": 3, "needle": "نزل عليك الكتاب"}}, {"ar": "أَنْزَلَ", "en": "sent down — said of the Torah and the Gospel in the same verse", "cite": {"surah": 3, "ayah": 3, "needle": "وانزل التوراة والانجيل"}}]');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('نزل', 'kmaps_root_dna', 'هُبُوطُ الشَّيْءِ مِنْ عُلْوٍ وَحُلُولُهُ بِمَكَانٍ', 'Coming down from a height and settling in a place.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('كتب', 'kmaps_root_dna', 'جَمْعُ شَيْءٍ إِلَى شَيْءٍ، ثُمَّ إِثْبَاتُهُ', 'Joining one thing to another — letters joined into writing; what is written is fixed and binding.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('عزز', 'kmaps_root_dna', 'الشِّدَّةُ وَالقُوَّةُ وَالامْتِنَاعُ؛ وَالأَرْضُ العَزَازُ: الصُّلْبَةُ', 'Hard strength that cannot be broken or overcome — like hard, solid ground.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('علم', 'kmaps_root_dna', 'أَثَرٌ بِالشَّيْءِ يَتَمَيَّزُ بِهِ عَنْ غَيْرِهِ', 'A mark by which a thing is known and told apart.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('غفر', 'kmaps_root_dna', 'السَّتْرُ وَالتَّغْطِيَةُ', 'Covering and shielding — like the helmet (مِغْفَر) that covers the head.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('ذنب', 'kmaps_root_dna', 'مُؤَخَّرُ الشَّيْءِ، وَمِنْهُ الذَّنَبُ', 'The tail — what comes at the end; a sin is a deed whose consequence follows behind it.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('قبل', 'kmaps_root_dna', 'مُوَاجَهَةُ الشَّيْءِ لِلشَّيْءِ', 'Facing — one thing meeting another face to face; to accept is to receive what comes to you.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('توب', 'kmaps_root_dna', 'الرُّجُوعُ', 'Returning — coming back.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('شدد', 'kmaps_root_dna', 'قُوَّةٌ فِي الشَّيْءِ', 'Tightness and strength — binding a thing firmly.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('عقب', 'kmaps_root_dna', 'تَأْخِيرُ شَيْءٍ وَإِتْيَانُهُ بَعْدَ غَيْرِهِ', 'Coming after — the heel, what follows behind.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('طول', 'kmaps_root_dna', 'فَضْلٌ وَامْتِدَادٌ فِي الشَّيْءِ', 'Stretching far — length, and a bounty that reaches others.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
INSERT OR REPLACE INTO qr_vocab_root_core (root, source_slug, text_ar, text_en, citation) VALUES ('اله', 'kmaps_root_dna', 'التَّعَبُّدُ: أَلَهَ إِلَاهَةً أَيْ عَبَدَ', 'The one turned to in worship and for refuge.', 'مقاييس اللغة · لين · لسان العرب · تاج العروس');
