UPDATE qr_study_label SET extra_json = json_set(extra_json, '$.step', json_extract(extra_json, '$.step') - 1)
 WHERE scope = 'class_node' AND key IN ('sentences', 'structure', 'questions', 'listen', 'tafsir', 'check');
-- translation choices left the Sentences step (who rendered it, its strategy, translator comparison)
