         '$.levels.middle.types', json('["antonym","bab","masdar","plural_pattern","form","odd","keyterm","particle"]'),
         '$.levels.advanced.types', json('["asl","tropical","order","quran_sense","disagree"]'))
 WHERE scope = 'skill' AND key = 'lexicon';
